(30911, 'Hebrews 6:4', 'Hebrews', 6, 4, 'ځکه په هغوی باندې چې یوځل د خدای د نور‌رڼایي راغلې ده، د اسماني نعمتونو خوند یې څکلی دی او په روح القدس کې شریک شوي دي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_4.mp3', '', 1761754199, 1761754199),
(30912, 'Hebrews 6:5', 'Hebrews', 6, 5, 'د خدای د کلام ښه‌والی او د راتلونکې زمانې قدرتونه یې تجربه کړي دي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_5.mp3', '', 1761754199, 1761754199),
(30913, 'Hebrews 6:6', 'Hebrews', 6, 6, 'او که د خدای د لارې څخه وګرځي، نو دا ناشونې ده چې هغوی به بېرته توبې ویستلو ته تیار کړای شي، ځکه چې هغوی یوځل بیا د خدای زوی په صلیب باندې مېخ کوي او د خلکو په مخکې یې شرموي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_6.mp3', '', 1761754199, 1761754199),
(30914, 'Hebrews 6:7', 'Hebrews', 6, 7, 'هغه ځمکه چې باران ورباندې وریږي او هغه جذب کړي او د کرونکو دپاره ګټور حاصل ورکړي، نو د خدای له خوا برکت مومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_7.mp3', '', 1761754199, 1761754199),
(30915, 'Hebrews 6:8', 'Hebrews', 6, 8, 'خو که هغه ځمکه اغزي او هرزه بوټي شنه کوي، نو دا بې‌ګټې ځمکه ده او زر به د خدای لعنت پرې وشي او په پای کې به هغه وسوځول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_8.mp3', '', 1761754199, 1761754199),
(30916, 'Hebrews 6:9', 'Hebrews', 6, 9, 'ګرانو دوستانو! سره له دې چې مونږ داسې خبرې کوو، خو ستاسو په هکله مونږ ډاډمن یو چې د خلاصون سره یوځای به د ډېرو ښو برکتونو څخه برخمن شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_9.mp3', '', 1761754199, 1761754199),
(30917, 'Hebrews 6:10', 'Hebrews', 6, 10, 'خدای بې‌انصافه نه دی. هغه به ستاسو کار او هغه مینه هېره نه کړي چې د هغه د نوم سره مو د هغه خلکو ته په خدمت کولو سره چې اوس یې هم کوئ ښودلې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_10.mp3', '', 1761754199, 1761754199),
(30918, 'Hebrews 6:11', 'Hebrews', 6, 11, 'مونږ ستاسو هر یو څخه ډېر غواړو چې همدا لېوالتیا تر اخره وساتئ، ترڅو ستاسو هیله چې د کوم شي دپاره یې لرئ، هغه پوره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_11.mp3', '', 1761754199, 1761754199),
(30919, 'Hebrews 6:12', 'Hebrews', 6, 12, 'مونږ نه غواړو چې تاسو دې لټان اوسئ، بلکې غواړو چې د هغو خلکو د مثال څخه پیروي وکړئ چې د ایمان او صبر په وسیله هغه څه تر‌لاسه کړي چې خدای یې وعده کړې ده. د خدای وعده هیله‌مندي پیدا کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_12.mp3', '', 1761754199, 1761754199),
(30920, 'Hebrews 6:13', 'Hebrews', 6, 13, 'کله چې خدای د ابراهیم سره وعده وکړه، نو په خپل نوم یې قسم وخوړ، ځکه چې د هغه څخه بل څوک لوی نه ؤ چې د هغه په نوم یې قسم خوړلی وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_13.mp3', '', 1761754199, 1761754199),
(30921, 'Hebrews 6:14', 'Hebrews', 6, 14, 'هغه وویل: «زه به په رښتیا سره تاته برکت درکړم او ستا اولادونه به زیات کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_14.mp3', '', 1761754199, 1761754199),
(30922, 'Hebrews 6:15', 'Hebrews', 6, 15, 'نو ابراهیم په صبر سره انتظار وکړ او هغه څه یې تر‌لاسه کړ چې خدای ورسره وعده کړې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_15.mp3', '', 1761754199, 1761754199),
(30923, 'Hebrews 6:16', 'Hebrews', 6, 16, 'کله چې انسانان قسم خوري، نو د خپل ځان څخه په لوی شي قسم خوري او همدا قسم د شخړو د پای ته رسېدلو سبب ګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_16.mp3', '', 1761754199, 1761754199),
(30924, 'Hebrews 6:17', 'Hebrews', 6, 17, 'همدارنګه خدای غوښتل چې په روښانه ډول هغو خلکو ته چې وعده یې ورسره کړې وه دا وښایي چې د هغه اراده نه بدلېدونکې ده، نو هغه یې د قسم په خوړلو سره تایید کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_17.mp3', '', 1761754199, 1761754199),
(30925, 'Hebrews 6:18', 'Hebrews', 6, 18, 'دلته دا دوه شیان دي چې نه بدلېدونکي دي، ځکه چې دا ناشونې ده چې خدای د هغو په هکله دروغ ووایي. نو مونږ چې هغه ته پناه وړې ده په ډېرې زړورتیا سره هغه هیله ټینګه ساتو چې زمونږ په وړاندې موجوده ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_18.mp3', '', 1761754199, 1761754199),
(30926, 'Hebrews 6:19', 'Hebrews', 6, 19, 'دا هیله چې مونږ یې لرو هغه زمونږ د ځانونو دپاره د یو قوي لنګر په شان دی. او دا داسې قوي او خوندي هیله ده چې مونږ د خدای د کور د پردې له لارې دننه ډېر سپېڅلي ځای ته رسوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_19.mp3', '', 1761754199, 1761754199),
(30927, 'Hebrews 6:20', 'Hebrews', 6, 20, 'یعنې هغه ځای ته چې عیسی زمونږ نه مخکې زمونږ دپاره هلته لاړ او د تل دپاره د ملک‌صدق په شان لوی کاهن شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews6_verse_20.mp3', '', 1761754199, 1761754199),
(30928, 'Hebrews 11:1', 'Hebrews', 11, 1, 'ایمان په هغو شیانو باندې باور لرل دي چې مونږ ورته هیله‌من یو او په هغو شیانو باندې ټینګه عقیده لرل چې مونږ یې نه شو لیدلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_1.mp3', '', 1761754199, 1761754199),
(30929, 'Hebrews 11:2', 'Hebrews', 11, 2, 'د ایمان په وسیله ؤ چې د پخوانۍ زمانې خلک د خدای له خوا ومنل شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_2.mp3', '', 1761754199, 1761754199),
(30930, 'Hebrews 11:3', 'Hebrews', 11, 3, 'مونږ د ایمان له مخې پوهېږو چې ټول کاینات د خدای د کلام په وسیله پیدا شو، نو څه چې مونږ وینو هغه د هغو شیانو څخه جوړ شوي دي چې نه شي لیدل کېدای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_3.mp3', '', 1761754199, 1761754199),
(30931, 'Hebrews 11:4', 'Hebrews', 11, 4, 'د ایمان په وسیله ؤ چې هابیل د قاین نه ډېره ښه قرباني خدای ته وړاندې کړه. هغه د خپل ایمان له لارې د خدای په نظر کې عادل وګنل شو، ځکه چې خدای د هغه نذرانې قبولې کړې او سره له دې چې هابیل مړ شوی دی، خو د خپل ایمان له لارې تر‌اوسه زمونږ سره خبرې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_4.mp3', '', 1761754199, 1761754199),
(30932, 'Hebrews 11:5', 'Hebrews', 11, 5, 'د ایمان په وسیله ؤ چې خنوخ مړ نه شو او اسمان ته پورته کړای شو او هېچا هغه پیدا نه کړ، ځکه چې خدای هغه پورته یووړ. مخکې له دې چې هغه پورته یووړل شي، د خدای کلام د هغه په هکله شاهدي ورکوي چې خدای د هغه څخه راضي ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_5.mp3', '', 1761754199, 1761754199),
(30933, 'Hebrews 11:6', 'Hebrews', 11, 6, 'نو پرته له ایمانه دا ناشونې ده چې انسان دې خدای خوشحاله کړي، ځکه څوک چې غواړي خدای ته ورنژدې شي، نو باید په دې ایمان ولري چې هغه موجود دی او څوک چې هغه لټوي، نو هغه ته اجر ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_6.mp3', '', 1761754199, 1761754199),
(30934, 'Hebrews 11:7', 'Hebrews', 11, 7, 'د نوح د ایمان په وسیله ؤ چې هغه ته د هغو شیانو په هکله خبرداری ورکړل شو چې لا تر هغه وخته نه وو پېښ شوي. هغه اطاعت وکړ او د خپلې کورنۍ د ژغورلو دپاره یې یوه لویه کشتۍ جوړه کړه. هغه د خپل ایمان له لارې دنیا محکومه کړه او د ایمان له مخې عادل وګڼل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_7.mp3', '', 1761754199, 1761754199),
(30935, 'Hebrews 11:8', 'Hebrews', 11, 8, 'کله چې خدای ابراهیم ته امر وکړ چې خپل کور پرېږدي او هغه ځای ته لاړ شي چې خدای به یې ورته د میراث په توګه ورکړي، د ایمان په وسیله ؤ چې هغه اطاعت وکړ او بې له دې چې پوه شي چېرته ځي، د خپل وطن نه ووت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_8.mp3', '', 1761754199, 1761754199),
(30936, 'Hebrews 11:9', 'Hebrews', 11, 9, 'د ایمان په وسیله لکه د یو پردي په شان په هغه وطن کې چې خدای ورسره وعده کړې وه، اوسېده او د اسحاق او یعقوب سره هم چې د دې وعدې وارثان وو، په خېمو کې اوسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_9.mp3', '', 1761754199, 1761754199),
(30937, 'Hebrews 11:10', 'Hebrews', 11, 10, 'ځکه چې ابراهیم د هغه ښار د لیدلو هیله درلودله چې ټینګ بنیاد لري او نقشه جوړوونکی او ودانوونکی یې خدای دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_10.mp3', '', 1761754199, 1761754199),
(30938, 'Hebrews 11:11', 'Hebrews', 11, 11, 'د ایمان په وسیله ؤ چې ساره وکولای شول ماشوم وزېږوي، که څه هم هغه شنډه او ډېره زړه وه، ځکه چې هغې باور درلود چې خدای په خپله وعده باندې وفا کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_11.mp3', '', 1761754199, 1761754199),
(30939, 'Hebrews 11:12', 'Hebrews', 11, 12, 'له همدې امله د یو سړي نه چې د مړي په شان ؤ، لکه په اسمان کې د ډېرو زیاتو ستورو او د بحیرې د غاړې د شګو په شان یې بې‌شمېره اولادونه پیدا شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_12.mp3', '', 1761754199, 1761754199),
(30940, 'Hebrews 11:13', 'Hebrews', 11, 13, 'هغه ټول خلک مړه شول، خو تر مرګه پورې په خپل ايمان کې پاتې شول، که څه هم هغوی هغه څه تر‌لاسه نه کړل چې وعده ورسره شوې وه. هغوی هغه شیان د لېرې څخه ولیدل، خو بیاهم خوشحاله وو او اقرار یې وکړ چې دوی په دې دنیا کې پردي او مسافر دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_13.mp3', '', 1761754199, 1761754199),
(30941, 'Hebrews 11:14', 'Hebrews', 11, 14, 'ځکه کوم خلک چې داسې خبرې کوي، د هغو نه دا معلومیږي چې هغوی د خپل ځان دپاره د یو وطن په لټه کې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_14.mp3', '', 1761754199, 1761754199),
(30942, 'Hebrews 11:15', 'Hebrews', 11, 15, 'که چېرې هغوی د هغه وطن ارمان کاوه چې ورڅخه راوتلي وو، نو د هغوی دپاره دا موقعه وه چې بېرته هلته لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_15.mp3', '', 1761754199, 1761754199),
(30943, 'Hebrews 11:16', 'Hebrews', 11, 16, 'خو هغوی د یو ډېر ښه ځای یعنې اسماني وطن په لټه کې وو. نو له همدې امله خدای په دې نه شرمیږي چې د هغوی د خدای په نوم یادیږي، ځکه چې د هغوی دپاره یې یو ښار تیار کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_16.mp3', '', 1761754199, 1761754199),
(30944, 'Hebrews 11:17', 'Hebrews', 11, 17, 'د ایمان په وسیله ؤ چې کله خدای ابراهیم ازمایه، نو هغه اسحاق د قربانۍ په توګه خدای ته وړاندې کړ. دا سړی چې خدای ورسره وعده کړې وه، دې ته تیار شو چې خپل یوازېنی زوی خدای ته قرباني کړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_17.mp3', '', 1761754199, 1761754199),
(30945, 'Hebrews 11:18', 'Hebrews', 11, 18, 'که څه هم خدای هغه ته ویلي وو: «ستا نسل به د اسحاق څخه حساب شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_18.mp3', '', 1761754199, 1761754199),
(30946, 'Hebrews 11:19', 'Hebrews', 11, 19, 'ابراهیم په دې فکر ؤ چې خدای کولای شي اسحاق د مرګ نه بېرته راژوندی کړي، نو خدای ابراهیم ته خپل زوی هماغسې بېرته ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_19.mp3', '', 1761754199, 1761754199),
(30947, 'Hebrews 11:20', 'Hebrews', 11, 20, 'د ایمان په وسیله ؤ چې اسحاق خپلو دوو زامنو، یعقوب او عیسو ته د هغوی د راتلونکي په پام کې نیولو سره برکت ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_20.mp3', '', 1761754199, 1761754199),
(30948, 'Hebrews 11:21', 'Hebrews', 11, 21, 'د ایمان په وسیله ؤ چې کله یعقوب مړ کېده، نو د یوسف دواړو زامنو ته یې برکت ورکړ او په داسې حال کې چې په خپله امسا باندې یې تکیه وهلې وه، د خدای عبادت یې وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_21.mp3', '', 1761754199, 1761754199),
(30949, 'Hebrews 11:22', 'Hebrews', 11, 22, 'د ایمان په وسیله ؤ چې کله یوسف مړ کېده، نو د مصر څخه یې د اسراییلو د وتلو په هکله خبرې وکړې او د خپل مړي د ښخولو په اړه یې هغوی ته لارښوونې وکړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_22.mp3', '', 1761754199, 1761754199),
(30950, 'Hebrews 11:23', 'Hebrews', 11, 23, 'د ایمان په وسیله ؤ چې کله موسی وزېږېده، مور او پلار یې ولیدل چې هغه یو ښکلی ماشوم دی، نو هغوی د پاچا د حکم څخه ونه وېرېدل او هغه ماشوم یې درې میاشتې پټ وساته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_23.mp3', '', 1761754199, 1761754199),
(30951, 'Hebrews 11:24', 'Hebrews', 11, 24, 'د ایمان په وسیله ؤ کله چې موسی لوی شو، نو د دې نه یې انکار وکړ چې هغه دې د فرعون د لور د زوی په نوم یاد شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_24.mp3', '', 1761754199, 1761754199),
(30952, 'Hebrews 11:25', 'Hebrews', 11, 25, 'هغه د یو لنډ‌محاله مودې د عیش او عشرت او د ګناه څخه ډک ژوند په ځای د خدای د خلکو سره د بد چلند زغمل غوره وګڼل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_25.mp3', '', 1761754199, 1761754199),
(30953, 'Hebrews 11:26', 'Hebrews', 11, 26, 'هغه د مسیح په خاطر د بې‌عزتۍ زغمل د مصر د ټولو خزانو نه بهتر وګڼل، ځکه چې هغه خپل راتلونکي اجر ته سترګې په لاره ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_26.mp3', '', 1761754199, 1761754199),
(30954, 'Hebrews 11:27', 'Hebrews', 11, 27, 'د ایمان په وسیله ؤ چې موسی د مصر څخه راووت او د فرعون د قهر څخه ونه وېرېده او په حوصله یې خپلې لارې ته دوام ورکړ، ځکه چې د هغه نظر په نه‌لیدونکي خدای ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_27.mp3', '', 1761754199, 1761754199),
(30955, 'Hebrews 11:28', 'Hebrews', 11, 28, 'د ایمان په وسیله ؤ چې موسی د اسراییلو خلکو ته حکم وکړ چې د فسحې اختر جوړ کړي او د حیواناتو وینه د دروازو په چوکاټونو باندې وشیندي، ترڅو د مرګ فرښته د اسراییلو لومړني زېږېدلي اولادونه ونه وژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_28.mp3', '', 1761754199, 1761754199),
(30956, 'Hebrews 11:29', 'Hebrews', 11, 29, 'د ایمان په وسیله ؤ چې د اسراییلو قوم د سرې بحیرې نه داسې پورې وتل لکه په وچه ځمکه چې تېر شي، خو کله چې مصریانو د پورې وتلو کوښښ وکړ، نو ډوب شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_29.mp3', '', 1761754199, 1761754199),
(30957, 'Hebrews 11:30', 'Hebrews', 11, 30, 'د ایمان په وسیله ؤ چې د اسراییلو خلک د اریحا د ښار نه اووه ورځې ګردچاپېره وګرځېدل او وروسته بیا د ښار دېوالونه راوغورځېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_30.mp3', '', 1761754199, 1761754199),
(30958, 'Hebrews 11:31', 'Hebrews', 11, 31, 'د ایمان په وسیله ؤ چې بدلمنه راحاب د نورو نافرمانه خلکو سره یوځای ونه وژل شوه، ځکه چې هغې اسراییلي جاسوسانو ته دوستانه هرکلی ویلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_31.mp3', '', 1761754199, 1761754199),
(30959, 'Hebrews 11:32', 'Hebrews', 11, 32, 'نور زه څه ووایم؟ ځکه چې زما زیات وخت نشته چې د جدعون، باراق، شمشون، یفتاح، داود، سموییل او نورو پیغمبرانو په هکله خبرې وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_32.mp3', '', 1761754199, 1761754199),
(30960, 'Hebrews 11:33', 'Hebrews', 11, 33, 'هغوی د ایمان په وسیله پاچاهي‌ګانې فتح کړې او عدالت یې ټینګ کړ او هغه شیان یې تر‌لاسه کړل چې خدای ورسره وعده کړې وه. هغوی د زمریانو خولې بندې کړې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_33.mp3', '', 1761754199, 1761754199),
(30961, 'Hebrews 11:34', 'Hebrews', 11, 34, 'د اور لمبې یې مړې کړې او د تورې د خولې نه خلاص شول. هغوی کمزوري وو، خو قوي شول. په جنګ کې زورور شول او د پردیو لښکرې یې تېښتې ته مجبورې کړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_34.mp3', '', 1761754199, 1761754199),
(30962, 'Hebrews 11:35', 'Hebrews', 11, 35, 'ښځو خپل مړي بیا ژوندي وموندل. ځینو نورو ډېر کړاوونه ولیدل، خو ازادي یې ونه منله، ترڅو د قیامت په ورځ له دې نه ډېر ښه ژوند ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_35.mp3', '', 1761754199, 1761754199),
(30963, 'Hebrews 11:36', 'Hebrews', 11, 36, 'په ځینو باندې ملنډې ووهل شوې، په دورو ووهل شول، نور په زنځیرونو وتړل شول او بندیان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_36.mp3', '', 1761754199, 1761754199),
(30964, 'Hebrews 11:37', 'Hebrews', 11, 37, 'هغوی سنګسار شول، په ارې باندې نیم کړای شول او په تورو باندې یې مړه کړل. هغوی د پسونو او وزو پوستکي اغوستي وو او د ډېرې غریبۍ، ظلم او کړاوونو له امله سرګردانه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_37.mp3', '', 1761754199, 1761754199),
(30965, 'Hebrews 11:38', 'Hebrews', 11, 38, 'دنیا د دې خلکو لیاقت نه درلود. هغوی په دښتو او غرونو کې سرګردانه ګرځېدل او په غارونو او سمڅو کې اوسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_38.mp3', '', 1761754199, 1761754199),
(30966, 'Hebrews 11:39', 'Hebrews', 11, 39, 'د خپل ایمان په وسیله د هغوی ټولو ښه ستاینه وشوه، خو بیا یې هم هغه څه تر‌لاسه نه کړل چې خدای یې وعده کړې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_39.mp3', '', 1761754199, 1761754199),
(30967, 'Hebrews 11:40', 'Hebrews', 11, 40, 'ځکه چې خدای زمونږ دپاره له مخکې نه ډېر ښه شی درلود چې وروسته به یې راکړي، هغه دا چې هغوی به زمونږ سره کامل کړای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews11_verse_40.mp3', '', 1761754199, 1761754199),
(30968, 'Matthew 14:1', 'Matthew', 14, 1, 'په دې وخت کې د جلیل والي هیرودیس د عیسی د کارونو څخه خبر شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_1.mp3', '', 1761754199, 1761754199),
(30969, 'Matthew 14:2', 'Matthew', 14, 2, 'نو خپلو کسانو ته یې وویل: «دا سړی هماغه تعمید ورکوونکی یحیی دی. هغه بېرته د مرګ نه راژوندی شوی دی، نو له دې امله هغه دا قدرت لري چې معجزې وښایي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_2.mp3', '', 1761754199, 1761754199),
(30970, 'Matthew 14:3', 'Matthew', 14, 3, 'هیرودیس د خپل ورور فیلیپوس د ښځې هیرودیا په خاطر یحیی نیولی ؤ، په زنځیرونو یې تړلی ؤ او په زندان کې یې اچولی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_3.mp3', '', 1761754199, 1761754199),
(30971, 'Matthew 14:4', 'Matthew', 14, 4, 'ځکه چې تعمید ورکوونکي یحیی هیرودیس ته ویلي وو: «تاته روا نه ده چې د خپل ورور د ښځې هیرودیا سره واده وکړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_4.mp3', '', 1761754199, 1761754199),
(30972, 'Matthew 14:5', 'Matthew', 14, 5, 'هیرودیس غوښتل چې هغه مړ کړي، خو د خلکو څخه وېرېده، ځکه چې خلکو هغه پیغمبر ګڼلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_5.mp3', '', 1761754199, 1761754199),
(30973, 'Matthew 14:6', 'Matthew', 14, 6, 'خو د هیرودیس د زېږېدنې په مېلمستیا کې د هیرودیا لور د مېلمنو په مخکې داسې نڅا وکړه چې هیرودیس دومره خوشحاله شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_6.mp3', '', 1761754199, 1761754199),
(30974, 'Matthew 14:7', 'Matthew', 14, 7, 'چې قسم یې وخوړ چې هغه ترې هرڅه وغواړي نو ورته به یې ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_7.mp3', '', 1761754199, 1761754199),
(30975, 'Matthew 14:8', 'Matthew', 14, 8, 'هغې د خپلې مور په لمسون وویل: «د تعمید غسل ورکوونکي یحیی سر راته په پتنوس کې راکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_8.mp3', '', 1761754199, 1761754199),
(30976, 'Matthew 14:9', 'Matthew', 14, 9, 'پاچا د خپلې خبرې څخه پښېمانه شو، خو هغه د خپل قسم په خاطر چې د مېلمنو په مخکې یې خوړلی ؤ، خپلو کسانو ته حکم وکړ چې د هغې غوښتنه دې پوره کړای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_9.mp3', '', 1761754199, 1761754199),
(30977, 'Matthew 14:10', 'Matthew', 14, 10, 'هغه خپل کسان ولېږل او په زندان کې یې د یحیی سر پرې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_10.mp3', '', 1761754199, 1761754199),
(30978, 'Matthew 14:11', 'Matthew', 14, 11, 'نو د هغه سر یې په یو پتنوس کې راوړ او هغې انجلۍ ته یې ورکړ او هغې خپلې مور ته یووړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_11.mp3', '', 1761754199, 1761754199),
(30979, 'Matthew 14:12', 'Matthew', 14, 12, 'بیا د یحیی شاګردان راغلل او د هغه مړی یې یووړ او ښخ یې کړ. هغوی لاړل او عیسی یې خبر کړ. عیسی پنځه زره کسانو ته ډوډۍ ورکوي (مرقوس ۶‏:‌۳۰‌‏-‌۴۴ او لوقا ۹‏:‌۱۰‌‏-‌۱۷ او یوحنا ۶‏:‌۱‌‏-‌۱۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_12.mp3', '', 1761754199, 1761754199),
(30980, 'Matthew 14:13', 'Matthew', 14, 13, 'کله چې عیسی د یحیی په هکله دا خبر واورېد، نو د هغه ځای څخه په کشتۍ کې یو ګوښه ځای ته یوازې لاړ. خو کله چې خلک خبر شول، نو د خپلو ښارونو څخه د وچې لارې نه په هغه پسې لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_13.mp3', '', 1761754199, 1761754199),
(30981, 'Matthew 14:14', 'Matthew', 14, 14, 'کله چې عیسی د کشتۍ څخه راښکته شو د خلکو یوه لویه ګڼه‌ګوڼه یې ولیدله، نو زړه یې ورباندې وسوځېد او د هغوی ناروغان یې روغ کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_14.mp3', '', 1761754199, 1761754199),
(30982, 'Matthew 14:15', 'Matthew', 14, 15, 'کله چې ماښام شو، شاګردان یې ورته راغلل او ویې ویل: «دا ځای خوشې دښته ده او ډېره ناوخته شوې ده، خلک کلیو ته ولېږه چې خپلو ځانونو ته د خوړلو دپاره کوم څه واخلي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_15.mp3', '', 1761754199, 1761754199),
(30983, 'Matthew 14:16', 'Matthew', 14, 16, 'عیسی وویل: «د دوی تګ ته اړتیا نشته، تاسو خپله هغوی ته کوم څه ورکړئ چې ویې خوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_16.mp3', '', 1761754199, 1761754199),
(30984, 'Matthew 14:17', 'Matthew', 14, 17, 'هغوی ځواب ورکړ: «زمونږ سره یوازې پنځه ډوډۍ او دوه ماهیان دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_17.mp3', '', 1761754199, 1761754199),
(30985, 'Matthew 14:18', 'Matthew', 14, 18, 'عیسی وویل: «هغه ماته راوړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_18.mp3', '', 1761754199, 1761754199),
(30986, 'Matthew 14:19', 'Matthew', 14, 19, 'بیا هغه خلکو ته حکم وکړ چې په واښو باندې کښېني. بیا یې هغه پنځه ډوډۍ او دوه ماهیان راواخیستل، اسمان ته یې وکتل، د خدای شکر یې وویست او ډوډۍ یې ماتې کړې، هغه یې شاګردانو ته ورکړې او شاګردانو هغه په خلکو باندې ووېشلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_19.mp3', '', 1761754199, 1761754199),
(30987, 'Matthew 14:20', 'Matthew', 14, 20, 'هغوی ټولو وخوړل او ماړه شول او څه چې ترې پاتې شوي وو، شاګردانو هغه راټول کړل او دولس ټوکرۍ ترې ډکې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_20.mp3', '', 1761754199, 1761754199),
(30988, 'Matthew 14:21', 'Matthew', 14, 21, 'د هغو خلکو شمېر چې ډوډۍ یې وخوړله پنځه زرو تنو ته رسېده چې په هغو کې ښځې او ماشومان شمېرل شوي نه وو. عیسی د اوبو دپاسه ګرځي (مرقوس ۶‏:‌۴۵‌‏-‌۵۲ او یوحنا ۶‏:‌۱۵‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_21.mp3', '', 1761754199, 1761754199),
(30989, 'Matthew 14:22', 'Matthew', 14, 22, 'بیا عیسی خپل شاګردان مجبور کړل چې کشتۍ ته وخېژي او د ده څخه مخکې د بحیرې بلې غاړې ته لاړ شي او له هغې وروسته یې خلک رخصت کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_22.mp3', '', 1761754199, 1761754199),
(30990, 'Matthew 14:23', 'Matthew', 14, 23, 'چې کله یې خلک رخصت کړل، نو خپله یو غره ته لاړ چې یوازې دعا وکړي او تر ماښامه پورې هلته یوازې پاتې ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_23.mp3', '', 1761754199, 1761754199),
(30991, 'Matthew 14:24', 'Matthew', 14, 24, 'په دې وخت کې کشتۍ د وچې څخه لېرې وه او د څپو له امله یې ټکانونه خوړل، ځکه چې باد ورته مخامخ لګېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_24.mp3', '', 1761754199, 1761754199),
(30992, 'Matthew 14:25', 'Matthew', 14, 25, 'سهار وختي چې لا تیاره وه، عیسی په داسې حال کې چې د اوبو دپاسه ګرځېده، شاګردانو ته ورغی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_25.mp3', '', 1761754199, 1761754199),
(30993, 'Matthew 14:26', 'Matthew', 14, 26, 'خو کله چې شاګردانو ولیدل چې هغه د اوبو دپاسه روان دی، نو ووېرېدل او ویې ویل: «دا د مړي ارواح ده.» نو د وېرې له لاسه یې چیغې ووهلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_26.mp3', '', 1761754199, 1761754199),
(30994, 'Matthew 14:27', 'Matthew', 14, 27, 'خو عیسی سمدلاسه د هغوی سره خبرې وکړې او ویې ویل: «زړور اوسئ. زه یم، مه وېرېږئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_27.mp3', '', 1761754199, 1761754199),
(30995, 'Matthew 14:28', 'Matthew', 14, 28, 'پطروس وویل: «ای استاذه! که چېرې دا ته یې، نو ماته امر وکړه چې زه هم د اوبو دپاسه درشم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_28.mp3', '', 1761754199, 1761754199),
(30996, 'Matthew 14:29', 'Matthew', 14, 29, 'عیسی وویل: «راشه.» نو پطروس د کشتۍ څخه ښکته شو او د اوبو دپاسه د عیسی خواته روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_29.mp3', '', 1761754199, 1761754199),
(30997, 'Matthew 14:30', 'Matthew', 14, 30, 'خو کله چې هغه ولیدل چې څومره زورور باد لګیږي، نو ووېرېده او کله چې په اوبو کې ډوبېده، نو چیغې یې ووهلې: «استاذه! ما وژغوره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_30.mp3', '', 1761754199, 1761754199),
(30998, 'Matthew 14:31', 'Matthew', 14, 31, 'عیسی سمدلاسه خپل لاس ور اوږد کړ او هغه یې راونیوه او ورته ویې ویل: «ستا ایمان څومره کمزوری دی. ولې دې شک وکړ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_31.mp3', '', 1761754199, 1761754199),
(30999, 'Matthew 14:32', 'Matthew', 14, 32, 'کله چې هغوی په کشتۍ کې سپاره شول، باد ودرېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_32.mp3', '', 1761754199, 1761754199),
(31000, 'Matthew 14:33', 'Matthew', 14, 33, 'نو په کشتۍ کې ناست کسان هغه ته په سجده شول او ویې ویل: «ته په رښتیا د خدای زوی یې.» په جنیسارت کې د ناروغانو جوړول (مرقوس ۶‏:‌۵۳‌‏-‌۵۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_33.mp3', '', 1761754199, 1761754199),
(31001, 'Matthew 14:34', 'Matthew', 14, 34, 'هغوی د بحیرې څخه پورې وتل او د جنیسارت سیمې ته ورسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_34.mp3', '', 1761754199, 1761754199),
(31002, 'Matthew 14:35', 'Matthew', 14, 35, 'کله چې د هغه ځای خلکو عیسی وپېژانده، نو هغوی شاوخوا ټولو سیمو ته خبر ورکړ او خلکو خپل ټول ناروغان عیسی ته راوستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_35.mp3', '', 1761754199, 1761754199),
(31003, 'Matthew 14:36', 'Matthew', 14, 36, 'هغه ته یې سوال وکړ چې د دوی ناروغانو ته دومره اجازه ورکړي چې یوازې د هغه لمنې ته لاس وروړي او هرچا چې ورته لاس وروړ، نو هغوی به بیخي روغېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew14_verse_36.mp3', '', 1761754199, 1761754199),
(31004, 'Matthew 23:1', 'Matthew', 23, 1, 'بیا عیسی خلکو او خپلو شاګردانو ته وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_1.mp3', '', 1761754199, 1761754199),
(31005, 'Matthew 23:2', 'Matthew', 23, 2, '«د شریعت عالمان او فریسیان د موسی په چوکۍ ناست دي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_2.mp3', '', 1761754199, 1761754199),
(31006, 'Matthew 23:3', 'Matthew', 23, 3, 'هغوی چې هرڅه درته وایي تاسو یې ومنئ او عمل ورباندې وکړئ، خو د هغوی په شان کارونه مه کوئ، ځکه دوی چې څه وایي عمل ورباندې نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_3.mp3', '', 1761754199, 1761754199),
(31007, 'Matthew 23:4', 'Matthew', 23, 4, 'هغوی درانه پنډونه تړي او د خلکو په اوږو یې باروي، خو خپله نه غواړي چې ګوتې هم ورته وروړي چې د پنډ په وړلو کې ورسره مرسته وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_4.mp3', '', 1761754199, 1761754199),
(31008, 'Matthew 23:5', 'Matthew', 23, 5, 'کوم کارونه چې هغوی یې کوي هغه د دې دپاره کوي چې خلک یې وویني، هغوی لوی لوی تعویذونه جوړوي او په خپل تندي او مټ باندې یې تړي او داسې چپنې اغوندي چې اوږده ځونډي لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_5.mp3', '', 1761754199, 1761754199),
(31009, 'Matthew 23:6', 'Matthew', 23, 6, 'هغوی دا خوښوي چې په مېلمستیاوو کې په ډېرو لوړو ځایونو کې کښېني او په کنیسو کې مخکې ځایونه ونیسي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_6.mp3', '', 1761754199, 1761754199),
(31010, 'Matthew 23:7', 'Matthew', 23, 7, 'او خلک ورته په بازارونو کې سلام واچوي او ‹استاذه، استاذه› ورته ووایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_7.mp3', '', 1761754199, 1761754199);